#define DMX_GRAPH_NO_MAIN
#include "dmx_graph.cpp"
#include "session_timeline_document_candidate.h"
#include <chrono>

int main(int argc,char**argv){try{
 if(argc<2||argc>3)throw std::runtime_error("session [scalar|vector3]");const std::string requested=argc==3?argv[2]:"scalar";if(requested!="scalar"&&requested!="vector3")throw std::runtime_error("unknown animation key kind");SessionTimelineDocumentCandidate doc(loadGraph(argv[1]));uint32_t layer=UINT32_MAX;size_t key=SIZE_MAX;
 for(uint32_t i=0;i<doc.graph().elements.size()&&layer==UINT32_MAX;++i){const auto&e=doc.graph().elements[i];const auto&type=doc.graph().strings.at(e.type);if((requested=="scalar"&&type!="DmeFloatLogLayer")||(requested=="vector3"&&type!="DmeVector3LogLayer"))continue;try{KeyTrack track(doc.graph(),e);if(!track.values->values.empty()){layer=i;key=track.values->values.size()>1?1:0;}}catch(const std::runtime_error&){}}
 if(layer==UINT32_MAX)throw std::runtime_error("session has no supported animation key");const auto original=doc.graph();const auto beforeTrack=KeyTrack(original,original.elements[layer]);const auto beforeTimes=beforeTrack.times->values,beforeValues=beforeTrack.values->values;const auto deletedTime=wireInt(beforeTimes[key]);
 if(!doc.deleteAnimationKey(layer,key)||!doc.dirty())throw std::runtime_error("key delete missing or not dirty");const auto&deleted=KeyTrack(doc.graph(),doc.graph().elements[layer]);if(deleted.times->values.size()+1!=beforeTimes.size()||deleted.values->values.size()+1!=beforeValues.size())throw std::runtime_error("key delete did not remove paired array entries");if(key<deleted.times->values.size()&&wireInt(deleted.times->values[key])==deletedTime)throw std::runtime_error("deleted key time remains at index");
 if(doc.undo()!=1||doc.dirty())throw std::runtime_error("key delete undo failed or did not return clean");const auto&undone=KeyTrack(doc.graph(),doc.graph().elements[layer]);if(undone.times->values.size()!=beforeTimes.size()||undone.values->values.size()!=beforeValues.size())throw std::runtime_error("key delete undo array sizes");auto same=[](const Value&a,const Value&b){return a.wire==b.wire&&a.reference==b.reference&&a.text==b.text;};for(size_t i=0;i<beforeTimes.size();++i)if(!same(undone.times->values[i],beforeTimes[i])||!same(undone.values->values[i],beforeValues[i]))throw std::runtime_error("key delete undo did not restore exact key arrays");
 if(doc.redo()!=1||!doc.dirty())throw std::runtime_error("key delete redo failed");const auto path="work/key-delete-roundtrip-"+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count())+".dmx";doc.saveAs(path.c_str());if(doc.dirty())throw std::runtime_error("saved key deletion remains dirty");const auto reopened=loadGraph(path.c_str());const auto&persisted=KeyTrack(reopened,reopened.elements[layer]);if(persisted.times->values.size()+1!=beforeTimes.size()||persisted.values->values.size()+1!=beforeValues.size())throw std::runtime_error("key delete save/reopen mismatch");std::cout<<"document_key_delete_checks=8 layer="<<layer<<" key="<<key<<" kind="<<requested<<" paired_arrays=true undo_redo=true save_reload=true\n";return 0;
 }catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
